pub enum Msg {
    Ping,
    Hello(String),
    Heartbeat(u32),
}

pub fn decode(bytes: &str) -> Result<Msg, String> {
    if bytes.contains("ping") {
        return Ok(Msg::Ping);
    }
    if let Some(value) = bytes.strip_prefix("v:2|hello:") {
        return Ok(Msg::Hello(value.into()));
    }
    if let Some(sequence) = bytes.strip_prefix("v:2|heartbeat:") {
        return sequence
            .parse::<u32>()
            .map(Msg::Heartbeat)
            .map_err(|_| "unknown".into());
    }
    Err("unknown".into())
}

pub fn encode(msg: &Msg) -> String {
    match msg {
        Msg::Ping => "ping".into(),
        Msg::Hello(value) => format!("v:2|hello:{value}"),
        Msg::Heartbeat(sequence) => format!("v:2|heartbeat:{sequence}"),
    }
}

pub fn ping_roundtrip() -> Result<Msg, String> {
    decode(&encode(&Msg::Ping))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn decodes_v2_hello_frame() {
        assert!(matches!(decode("v:2|hello:world"), Ok(Msg::Hello(value)) if value == "world"));
    }

    #[test]
    fn encodes_v2_hello_frame() {
        assert_eq!(encode(&Msg::Hello("world".into())), "v:2|hello:world");
    }

    #[test]
    fn encodes_v2_heartbeat_frame() {
        assert_eq!(encode(&Msg::Heartbeat(42)), "v:2|heartbeat:42");
    }

    #[test]
    fn heartbeat_roundtrip() {
        assert!(matches!(decode(&encode(&Msg::Heartbeat(42))), Ok(Msg::Heartbeat(42))));
    }
}
